#!/usr/bin/env python3
"""
Round nh5 (culprits-tiles-more), 17 October 2026, from the Invasion of
non-humans chat. Carries every nonhuman_*.py and its two lib files (round
nh4's mends included), so it works whether or not nonhuman4_tiles.py was
applied. Each file is written only if it differs; they write only under
nonhuman/.

Changed:
  lib/nhwdpa.py             the protected-areas release is read straight from its zip, 20,000
                            at a time (inner zips copied out one at a time and deleted), never
                            unpacked whole: papressure and oilgas were stopped by the runner
                            minutes after the 4.8 GB download (disk or memory)
  nonhuman_papressure.py    measures each batch as it is read and keeps only the figures
  nonhuman_trawl_mpas.py    keeps only marine areas as they are read

Afterwards, Actions > refresh > Run workflow with
  nonhuman_papressure nonhuman_oilgas nonhuman_extraction
(plus round nh4's list if it has not been run yet).
Run from the repository root (apply-patch does).
"""
import base64, pathlib, sys

FILES = {
    'scripts/nonhuman_anthromes.py': '',
    'scripts/nonhuman_bannedexports.py': '',
    'scripts/nonhuman_devpotential.py': '',
    'scripts/nonhuman_extraction.py': '',
    'scripts/nonhuman_faostat.py': '',
    'scripts/nonhuman_firsts.py': '',
    'scripts/nonhuman_griis.py': '',
    'scripts/nonhuman_invacost.py': '',
    'scripts/nonhuman_oilgas.py': '',
    'scripts/nonhuman_paddd.py': '',
    'scripts/nonhuman_panbans.py': '',
    'scripts/nonhuman_papressure.py': '',
    'scripts/nonhuman_pestco.py': '',
    'scripts/nonhuman_pestgrids.py': '',
    'scripts/nonhuman_pestplants.py': '',
    'scripts/nonhuman_pestrisk.py': '',
    'scripts/nonhuman_roads.py': '',
    'scripts/nonhuman_trawl_mpas.py': '',
    'scripts/nonhuman_urban2100.py': '',
    'scripts/nonhuman_wetlands.py': '',
    'scripts/nonhuman_wgi.py': '',
    'scripts/lib/nhcommon.py': '',
    'scripts/lib/nhwdpa.py': '',
}


def main():
    if not pathlib.Path("scripts").is_dir():
        sys.exit("nonhuman5_tiles: run from the culprits-tiles-more repository root")
    changed = 0
    for path, b64 in FILES.items():
        data = base64.b64decode(b64)
        p = pathlib.Path(path)
        if p.exists() and p.read_bytes() == data:
            continue
        p.parent.mkdir(parents=True, exist_ok=True)
        p.write_bytes(data)
        changed += 1
        print(f"nonhuman5_tiles: wrote {path}")
    if not changed:
        print("nonhuman5_tiles: already applied")


if __name__ == "__main__":
    main()
